script:
function _qs(sel){return root_element.querySelector(sel);}
function _qsa(sel){return Array.from(root_element.querySelectorAll(sel));}

function _setText(el, v){ if(!el) return; el.textContent = (v===null||v===undefined||v==="") ? "—" : String(v); }
function _fmtInt(v){ const n = Number(v||0); return Number.isFinite(n) ? String(Math.trunc(n)) : "0"; }

function _routeFromData(btn){
  try{ return JSON.parse(btn.getAttribute('data-route')); }catch(e){ return null; }
}

function _wireMenu(){
  const menu = _qs('[data-menu]');
  if(!menu) return;
  menu.querySelectorAll('button[data-route]').forEach((btn)=>{
    btn.addEventListener('click', ()=>{
      const r = _routeFromData(btn);
      if(!r || !r.length) return;
      frappe.set_route.apply(frappe, r);
    });
  });

  const input = _qs('.tif-trustee__searchInput');
  if(input){
    input.addEventListener('input', ()=>{
      const q = (input.value||'').trim().toLowerCase();
      menu.querySelectorAll('button[data-route]').forEach((b)=>{
        const t = (b.textContent||'').toLowerCase();
        b.style.display = !q || t.includes(q) ? '' : 'none';
      });
    });
  }
}

function _dateStr(d){ return frappe.datetime.str_to_user(d); }

async function _loadAttendance(){
  const note = _qs('[data-note]');
  const table = _qs('[data-table]');
  const rangeEl = _qs('.tif-trustee__range');
  const days = Number(rangeEl?.value || 30);

  if(note){ note.style.display = 'none'; note.textContent = ''; }
  if(table){ table.innerHTML = '<div class="tif-trustee__tableEmpty">Loading…</div>'; }

  const to_date = frappe.datetime.get_today();
  const from_date = frappe.datetime.add_days(to_date, -Math.max(days-1,0));

  let data = {};
  try{
    const r = await frappe.call({
      method: 'tif_customization.tif_customization.trustee_dashboard.get_my_attendance_summary',
      args: { filters: { from_date, to_date, limit: 60 } },
    });
    data = r?.message || {};
  }catch(e){
    data = { rows: [], counts: {}, note: 'Could not load attendance.' };
  }

  const counts = data.counts || {};
  _qsa('[data-kpi]').forEach((el)=>{
    const k = el.getAttribute('data-kpi');
    _setText(el, _fmtInt(counts[k] || 0));
  });

  if(data.note && note){
    note.style.display = '';
    note.textContent = data.note;
  }

  const rows = data.rows || [];
  if(!table) return;
  if(!rows.length){
    table.innerHTML = '<div class="tif-trustee__tableEmpty">No attendance records in this range</div>';
    return;
  }

  const html = [
    '<table>',
    '<thead><tr><th>Date</th><th>Status</th></tr></thead>',
    '<tbody>',
    ...rows.map((r)=>{
      const dt = r.attendance_date ? _dateStr(r.attendance_date) : '';
      const st = (r.status || '—');
      return `<tr class="tif-row" data-name="${frappe.utils.escape_html(r.name || '')}"><td>${frappe.utils.escape_html(dt)}</td><td>${frappe.utils.escape_html(st)}</td></tr>`;
    }),
    '</tbody></table>'
  ].join('');
  table.innerHTML = html;
  table.querySelectorAll('tr.tif-row').forEach((tr)=>{
    tr.addEventListener('click', ()=>{
      const name = tr.getAttribute('data-name');
      if(name) frappe.set_route('Form','Attendance',name);
    });
  });
}

function _wireAttendance(){
  const btn = _qs('[data-refresh]');
  const rangeEl = _qs('.tif-trustee__range');
  if(btn) btn.addEventListener('click', ()=>_loadAttendance());
  if(rangeEl) rangeEl.addEventListener('change', ()=>_loadAttendance());
}

_wireMenu();
_wireAttendance();
_loadAttendance();

style:
.tif-trustee{font-family:inherit;}
.tif-trustee__header{display:flex;align-items:flex-end;justify-content:space-between;gap:12px;margin-bottom:12px;flex-wrap:wrap}
.tif-trustee__title{font-size:18px;font-weight:800;color:var(--text-color,#0f172a)}
.tif-trustee__sub{font-size:12px;color:var(--text-muted,#64748b)}
.tif-trustee__searchInput{min-width:240px;border:1px solid var(--border-color,#e5e7eb);border-radius:10px;padding:10px 12px;font-size:14px}
.tif-trustee__menu{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px;margin-bottom:12px}
@media(max-width:1200px){.tif-trustee__menu{grid-template-columns:repeat(2,minmax(0,1fr));}}
@media(max-width:700px){.tif-trustee__menu{grid-template-columns:1fr;}}
.tif-trustee__btn{border:1px solid var(--border-color,#e5e7eb);background:var(--card-bg,#fff);border-radius:12px;padding:14px 14px;font-size:16px;font-weight:700;text-align:left;cursor:pointer}
.tif-trustee__btn:hover{background:var(--control-bg,#f8fafc)}
.tif-trustee__btn--secondary{font-size:14px;padding:10px 12px}
.tif-trustee__panel{border:1px solid var(--border-color,#e5e7eb);border-radius:14px;background:var(--card-bg,#fff);padding:12px}
.tif-trustee__panelHead{display:flex;align-items:center;justify-content:space-between;gap:10px;flex-wrap:wrap;margin-bottom:10px}
.tif-trustee__panelTitle{font-size:15px;font-weight:800}
.tif-trustee__panelSub{font-size:12px;color:var(--text-muted,#64748b)}
.tif-trustee__controls{display:flex;gap:8px;align-items:center}
.tif-trustee__range{border:1px solid var(--border-color,#e5e7eb);border-radius:10px;padding:8px 10px;font-size:14px}
.tif-trustee__kpis{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:10px;margin:10px 0 6px}
@media(max-width:900px){.tif-trustee__kpis{grid-template-columns:repeat(2,minmax(0,1fr));}}
.tif-trustee__kpi{border:1px solid var(--border-color,#e5e7eb);border-radius:12px;padding:10px;background:var(--control-bg,#f8fafc)}
.tif-trustee__kpi .k{font-size:12px;color:var(--text-muted,#64748b);font-weight:700}
.tif-trustee__kpi .v{font-size:20px;font-weight:800;margin-top:4px}
.tif-trustee__note{margin:8px 0;padding:10px;border-radius:12px;background:#fff7ed;border:1px solid #fed7aa;color:#9a3412;font-size:12px;font-weight:600}
.tif-trustee__table table{width:100%;border-collapse:collapse}
.tif-trustee__table th,.tif-trustee__table td{border-top:1px solid var(--border-color,#e5e7eb);padding:10px 8px;font-size:14px}
.tif-trustee__table th{color:var(--text-muted,#64748b);font-weight:800;text-align:left}
.tif-trustee__table tr.tif-row{cursor:pointer}
.tif-trustee__table tr.tif-row:hover{background:var(--control-bg,#f8fafc)}
.tif-trustee__tableEmpty{font-size:13px;color:var(--text-muted,#64748b);padding:10px}
